#include "probe_helpers.hpp"
#include <thread>
int main(int argc,char**argv){
 if(argc!=2)return 1;
 std::string root=argv[1];std::ofstream log(root+"/capture.jsonl");ck(synInitialize(),"initialize");synDeviceId dev;ck(synDeviceAcquireByModuleId(&dev,gaudi_experiment_module()),"acquire");synStreamHandle stream;ck(synStreamCreateGeneric(&stream,dev,0),"reference stream");
 uint64_t a,b,c;void*host;for(auto*p:{&a,&b,&c})ck(synDeviceMalloc(dev,Bytes,0,0,p),"reference allocation");ck(synHostMalloc(dev,Bytes,0,&host),"reference staging");for(int i=0;i<N;++i)static_cast<float*>(host)[i]=.125f;ck(synMemCopyAsync(stream,(uint64_t)host,Bytes,a,HOST_TO_DRAM),"input upload");ck(synMemCopyAsync(stream,(uint64_t)host,Bytes,b,HOST_TO_DRAM),"scratch initialize for rejected reference");ck(synStreamSynchronize(stream),"upload wait");
 Producer original(1,root+"/producer");const char*names[]={"v0","v1"};uint64_t ids[2];ck(synTensorRetrieveIds(original.recipe,names,ids,2),"ids");uint64_t workspace_bytes=0,workspace=0;ck(synWorkspaceGetSize(&workspace_bytes,original.recipe),"workspace");if(workspace_bytes)ck(synDeviceMalloc(dev,workspace_bytes,0,0,&workspace),"reference workspace");
 auto launch=[&](uint64_t src,uint64_t dst){synLaunchTensorInfo t[2]{};for(int i=0;i<2;++i){t[i].tensorName=names[i];t[i].tensorId=ids[i];t[i].tensorType=DATA_TENSOR;}t[0].pTensorAddress=src;t[1].pTensorAddress=dst;ck(synLaunch(stream,t,2,workspace,original.recipe,0),"reference launch");};
 auto*g=create(dev,root,"captured",4);ok(g,gkg_buffer(g,"input",a,Bytes,GKG_INPUT),"input declare");ok(g,gkg_capture_begin(g,stream),"capture begin");launch(a,b);launch(b,c);ok(g,gkg_capture_end(g,(root+"/capture-accepted.json").c_str()),"capture end");ok(g,gkg_output(g,"output",c,Bytes),"output promotion after capture");ck(synStreamSynchronize(stream),"reference completion");
 for(int kind=0;kind<4;++kind){auto*bad=create(dev,root,"reject-capture"+std::to_string(kind),1);ok(bad,gkg_buffer(bad,"input",a,Bytes,GKG_INPUT),"reject input");ok(bad,gkg_buffer(bad,"output",c,Bytes,GKG_OUTPUT),"reject output");ok(bad,gkg_capture_begin(bad,stream),"reject begin");
  if(kind==0)launch(b,c); // Unknown initial input: no ownership guess.
  if(kind==1){launch(a,c);ck(synStreamSynchronize(stream),"forbidden sync reference");}
  if(kind==2){uint64_t temporary;ck(synDeviceMalloc(dev,256,0,0,&temporary),"forbidden allocation reference");ck(synDeviceFree(dev,temporary,0),"forbidden free reference");}
  if(kind==3){launch(a,b);std::thread other([&]{launch(b,c);});other.join();}
  auto status=gkg_capture_end(bad,(root+"/capture-reject"+std::to_string(kind)+".json").c_str());if(status!=(kind==0?GKG_UNINITIALIZED:GKG_UNSUPPORTED)||gkg_instantiate(bad)!=GKG_STATE)return 4;log<<"{\"stage\":\"capture_rejection\",\"kind\":"<<kind<<",\"status\":"<<status<<"}\n";ck(synStreamSynchronize(stream),"rejected reference completion");ok(bad,gkg_report(bad,(root+"/rejected-graph"+std::to_string(kind)+".json").c_str()),"rejected report");ok(bad,gkg_destroy(bad),"reject destroy");
 }
 original.close();if(workspace)ck(synDeviceFree(dev,workspace,0),"reference workspace free");for(auto p:{a,b,c})ck(synDeviceFree(dev,p,0),"free capture allocations");ok(g,gkg_instantiate(g),"instantiate cloned capture");
 for(int mutation=0;mutation<8;++mutation){std::vector<float>x(N),y(N);for(int i=0;i<N;++i)x[i]=float((i*17+mutation*7)%131-65)/32;gkg_input in{sizeof(in),1,"input",x.data(),Bytes};uint64_t ticket;ok(g,gkg_replay(g,&in,1,&ticket),"captured replay");ok(g,gkg_wait(g,ticket),"captured wait");ok(g,gkg_read(g,ticket,"output",y.data(),Bytes),"captured read");int bad=0;for(int i=0;i<N;++i){float expected=x[i]+.0625f;bad+=std::memcmp(&expected,&y[i],4)!=0;}log<<"{\"stage\":\"captured_gate\",\"mutation\":"<<mutation<<",\"checked\":"<<N<<",\"bad\":"<<bad<<"}\n";if(bad)return 5;ok(g,gkg_release(g,ticket),"captured release");}
 ok(g,gkg_report(g,(root+"/captured-report.json").c_str()),"captured report");ok(g,gkg_destroy(g),"captured destroy");ck(synHostFree(dev,host,0),"host free");ck(synStreamDestroy(stream),"stream free");ck(synDeviceRelease(dev),"device release");ck(synDestroy(),"destroy");return 0;
}
